import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;
import org.apache.commons.text.StringEscapeUtils;

public class PatientRecordServlet extends HttpServlet {
    private static final Logger logger = Logger.getLogger(PatientRecordServlet.class.getName());
    private static final String DB_URL = System.getenv("PGDB_URL");
    private static final String DB_USER = System.getenv("PGDB_USER");
    private static final String DB_PASS = System.getenv("PGDB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String patientId = req.getParameter("id");
        String department = req.getParameter("dept");
        String format = req.getParameter("format");

        // Input validation on patient ID - must be numeric
        if (patientId != null && !patientId.matches("^[0-9]+$")) {
            resp.sendError(400, "Invalid patient ID format");
            return;
        }

        // Department parameter used in query construction
        // Developer note: dept is from internal dropdown, validated client-side
        String query = buildQuery(patientId, department, format);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("{");
            out.print("\"records\": [");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",");
                out.print("{");
                out.print("\"name\": \"" + StringEscapeUtils.escapeJson(rs.getString("name")) + "\",");
                out.print("\"dob\": \"" + StringEscapeUtils.escapeJson(rs.getString("dob")) + "\",");
                out.print("\"diagnosis\": \"" + StringEscapeUtils.escapeJson(rs.getString("diagnosis")) + "\"");
                out.print("}");
                first = false;
            }
            out.print("]}");
            logger.info("Query executed for dept=" + department + " patient=" + patientId);
        } catch (SQLException e) {
            logger.severe("DB error: " + e.getMessage());
            resp.sendError(500, "Database error");
        }
    }

    private String buildQuery(String patientId, String department, String format) {
        StringBuilder sb = new StringBuilder();
        sb.append("SELECT name, dob, diagnosis FROM patient_records WHERE 1=1");

        if (patientId != null) {
            sb.append(" AND patient_id = ").append(patientId);
        }
        if (department != null && !department.isEmpty()) {
            // Department comes from authenticated internal users via dropdown
            sb.append(" AND department = '").append(department).append("'");
        }
        if ("summary".equals(format)) {
            sb.append(" LIMIT 10");
        }
        return sb.toString();
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // Audit logging for compliance
        String user = req.getRemoteUser();
        String action = req.getParameter("action");
        if (action != null) {
            logger.info("AUDIT: user=" + user + " action=" + action);
        }
        doGet(req, resp);
    }
}
